import Foundation
// Tests for the native Kosmos+ account screen's logic (kosmos#8959 slice B1a), compiled for macOS with AccountLogic.swift
// alone (run-account.sh). It prints every case and ends with one verdict line; a missing verdict means it did not finish.
// The expected words are the web account page's own (kosmos-relay coordinator/src/signin.html macWhen, askRetire,
// signout-all-yes), copied here: that page lives in the other repo, so this suite cannot read it.
setvbuf(stdout, nil, _IOLBF, 0)
var passed = 0
var failed = 0
func check(_ cond: @autoclosure () -> Bool, _ name: String, line: Int = #line) {
    if cond() { passed += 1; print("  ok   \(name)") } else { failed += 1; print("  FAIL \(name) (line \(line))") }
}
func section(_ name: String) { print(name) }
func json(_ s: String) -> Data { Data(s.utf8) }
let coordinator = URL(string: "https://login.kosmosplus.com")!
let now: Double = 1_800_000_000
typealias C = Account.Computer

section("the list: every row kept, as Kosmos+ sends it")
let rows = Account.parseComputers(json(#"""
{"macs":[
 {"name":"studio","address":"studio.kosmosplus.com","last_seen":1799999990,"retired_at":null,"remote_off":false,"not_connected":false,"held":false,"refused":false,"updating_until":null},
 {"name":"old","address":"old.kosmosplus.com","last_seen":1700000000,"retired_at":1750000000},
 {"name":"old","address":"old.kosmosplus.com","last_seen":0},
 {"name":"waiting","held":true,"last_seen":1799990000},
 {"name":"","address":"x.kosmosplus.com"},
 {"name":"upd","last_seen":1799999000,"updating_until":1800000100}
]}
"""#))
check(rows?.count == 5, "a row with no name is dropped (Retire needs the name); the other five are kept")
check(rows?[0] == C(name: "studio", lastSeen: 1799999990, position: 0), "a plain computer: name, last heard from, nothing else set")
check(rows?[1].retired == true && rows?[2].retired == false, "retired_at is read as retired, null or missing as not")
check(rows?[2].lastSeen == nil, "last_seen 0 is never heard from, not 1970")
check(rows?[3].held == true && rows?[4].updating == true, "held and updating_until are read")
check(Set(rows?.map(\.id) ?? []).count == 5 && rows?[1].name == rows?[2].name, "two rows with one name (retired, then set up again) are two rows")
let zeros = Account.parseComputers(json(#"{"macs":[{"name":"z","last_seen":1799999990,"retired_at":0,"updating_until":0}]}"#))
check(zeros?.first?.retired == false && zeros?.first?.updating == false, "a time of 0 is unset, as the page tests it")
check(Account.parseComputers(json(#"{"error":"x"}"#)) == nil && Account.parseComputers(nil) == nil, "an answer with no list is not an empty list")
check(Account.parseComputers(json(#"{"macs":[]}"#)) == [], "an empty list is no computers")

section("the words: the web page's macWhen, word for word")
func w(_ c: C, allow: Int = 1) -> String { Account.words(c, now: now, canAllow: allow) }
check(w(C(name: "a", lastSeen: now - 30)) == "Answering now", "heard from under two minutes ago: Answering now")
check(w(C(name: "a", lastSeen: now - 30 * 60)) == "Answered 30 minutes ago", "minutes")
check(w(C(name: "a", lastSeen: now - 60)) == "Answering now" && w(C(name: "a", lastSeen: now - 119)) == "Answering now" && w(C(name: "a", lastSeen: now - 120)) == "Answered 2 minutes ago", "the two-minute edge")
check(w(C(name: "a", lastSeen: now - 5 * 3600)) == "Answered 5 hours ago", "hours")
check(w(C(name: "a", lastSeen: now - 3600)) == "Answered 1 hour ago", "one hour, not one hours")
check(w(C(name: "a", lastSeen: now - 3 * 86400)) == "Answered 3 days ago", "days, under the fortnight")
check(w(C(name: "a", lastSeen: now - 172799)) == "Answered 48 hours ago" && w(C(name: "a", lastSeen: now - 172800)) == "Answered 2 days ago", "hours turn to days at 48 hours")
check(w(C(name: "a", lastSeen: now - 3599)) == "Answered 60 minutes ago" && w(C(name: "a", lastSeen: now - 3600)) == "Answered 1 hour ago", "minutes turn to hours at an hour")
check(Account.ago(150) == "3 minutes ago" && Account.count(1, "minute") == "1 minute", "rounded as the page rounds; one minute, not one minutes")
check(w(C(name: "a", lastSeen: now - (14 * 86400 - 1))) == "Answered 14 days ago" && w(C(name: "a", lastSeen: now - 14 * 86400)) == "Has not answered in 14 days. It may be off, or gone.", "the fortnight edge")
check(!Account.stale(C(name: "a", lastSeen: now - (14 * 86400 - 1)), now: now) && Account.stale(C(name: "a", lastSeen: now - 14 * 86400), now: now), "dimmer from the fortnight on, not before")
check(w(C(name: "a", lastSeen: now - 20 * 86400, remoteOff: true)) == "Has not answered in 20 days. It may be off, or gone." && w(C(name: "a", lastSeen: now - 20 * 86400, notConnected: true)) == "Has not answered in 20 days. It may be off, or gone.", "remote access off or not connected, silent a fortnight: may be off, or gone")
check(w(C(name: "a", lastSeen: now - 20 * 86400)) == "Has not answered in 20 days. It may be off, or gone.", "silent a fortnight or more")
check(w(C(name: "a")) == "Has not answered yet.", "never heard from")
check(w(C(name: "a", lastSeen: now, retired: true)) == "Retired. Its address is free again.", "retired comes first")
check(w(C(name: "a", lastSeen: now - 30, updating: true)) == "Applying an update, back in a moment.", "an update is not silence")
check(w(C(name: "a", lastSeen: now - 600, remoteOff: true)) == "Remote access off, last heard from 10 minutes ago", "remote access off is never Answering now")
check(w(C(name: "a", lastSeen: now - 30, notConnected: true)) == "Remote access on, but not connected, last heard from just now", "not connected")
check(w(C(name: "a", lastSeen: now - 600, refused: true)) == "Not allowed on your account. Retire it, and set it up again if it is yours. Last heard from 10 minutes ago.", "refused")
check(w(C(name: "a", held: true), allow: 2) == "Waiting for approval on one of your other computers. If you did not set it up, do not allow it there. It has not answered yet.", "waiting, two others can allow")
check(w(C(name: "a", lastSeen: now - 30, held: true), allow: 1) == "Waiting for approval on your other computer. If you did not set it up, do not allow it there. Last heard from just now.", "waiting, one other")
check(w(C(name: "a", held: true), allow: 0) == "Waiting to be allowed, but no other computer on your account is left to allow it. Retire it and set it up again. It has not answered yet.", "waiting, nobody left to allow it")
check(Account.canAllow([C(name: "a"), C(name: "b", retired: true), C(name: "c", held: true), C(name: "d", refused: true)]) == 1, "only a computer neither retired, waiting nor refused can allow")
check(Account.stale(C(name: "a"), now: now) && Account.stale(C(name: "a", lastSeen: now - 15 * 86400), now: now), "never heard from, or silent a fortnight: dimmer")
check(!Account.stale(C(name: "a", lastSeen: now - 15 * 86400, retired: true), now: now) && !Account.stale(C(name: "a", held: true), now: now), "retired and waiting have their own look")

section("the requests")
let retire = Account.retireRequest(coordinator: coordinator, session: "s1", name: "studio")
let body = (try? JSONSerialization.jsonObject(with: retire.httpBody ?? Data())) as? [String: Any]
check(retire.httpMethod == "POST" && retire.url?.absoluteString == "https://login.kosmosplus.com/v1/account/macs/remove", "retire is POST /v1/account/macs/remove")
check(body?["name"] as? String == "studio" && body?["confirm"] == nil, "the first ask carries the name and no code")
let retire2 = Account.retireRequest(coordinator: coordinator, session: "s1", name: "studio", confirm: "K7QX")
check(((try? JSONSerialization.jsonObject(with: retire2.httpBody ?? Data())) as? [String: Any])?["confirm"] as? String == "K7QX", "the second carries the typed code")
check(retire.value(forHTTPHeaderField: "Authorization") == "Bearer s1" && !retire.httpShouldHandleCookies, "the session goes as the Bearer, with no cookie jar")
let forget = Account.forgetRequest(coordinator: coordinator, session: "s1")
check(forget.url?.path == "/v1/session/forget" && forget.value(forHTTPHeaderField: "x-kosmos-web") == "1" && forget.value(forHTTPHeaderField: "Authorization") == "Bearer s1", "sign out is /v1/session/forget with the header the route requires")
check(Account.signOutEverywhereRequest(coordinator: coordinator, session: "s1").url?.path == "/v1/account/sign-out-everywhere", "sign out everywhere")
check(Account.signOutEverywhereRequest(coordinator: coordinator, session: "s1").value(forHTTPHeaderField: "x-kosmos-web") == nil, "only forget carries the page header")

section("retire: the code comes from Kosmos+, never from the app")
let ask = json(#"{"confirm":"K7QX","name":"studio","message":"type K7QX to retire studio; it will stop answering and its name is free again after a day"}"#)
check(Account.retireAnswer(status: 409, data: ask, name: "studio", typed: nil) == .confirm(code: "K7QX", words: "Type K7QX to retire studio; it will stop answering and its name is free again after a day."), "409 with a code: Kosmos+'s own sentence, capitalised")
check(Account.retireAnswer(status: 409, data: json(#"{"confirm":"K7QX"}"#), name: "studio", typed: nil) == .confirm(code: "K7QX", words: "Type K7QX to retire studio."), "no sentence: the page's own fallback")
check(Account.retireAnswer(status: 409, data: ask, name: "studio", typed: "ABCD") == .refused("That is not the code shown for studio. Nothing was retired."), "a wrong code is said, not shown again as if nothing happened")
check(Account.retireAnswer(status: 200, data: json(#"{"ok":true,"name":"studio"}"#), name: "studio", typed: "K7QX") == .retired, "200 ok: retired")
check(Account.retireAnswer(status: 200, data: json(#"{}"#), name: "studio", typed: "K7QX") == .refused(Account.tryAgain), "200 without ok is not taken as retired")
check(Account.retireAnswer(status: 403, data: json(#"{"error":"that computer has been heard from in the last day; allow this device on one of your computers first, or retire it once it has been silent for a day","code":"recently_online"}"#), name: "studio", typed: nil)
      == .refused("That computer has been heard from in the last day; allow this device on one of your computers first, or retire it once it has been silent for a day."), "a refusal shows Kosmos+'s reason")
check(Account.retireAnswer(status: nil, data: nil, name: "studio", typed: nil) == .refused(Account.reach), "no answer: could not reach")
check(Account.typedCode("  k7qx \n") == "K7QX", "typed: trimmed and upper case, as the page reads it")

section("sign out: this iPhone signs out only once Kosmos+ has ended it, or the person chooses")
check(Account.forgetAnswer(status: 200) == .signOutHere && Account.forgetAnswer(status: 401) == .signOutHere, "200, or 401 (nothing left to end): sign out here")
check(Account.forgetAnswer(status: 500) == .stay(Account.forgetFailed) && Account.forgetAnswer(status: nil) == .stay(Account.forgetFailed) && Account.forgetAnswer(status: 403) == .stay(Account.forgetFailed), "anything else stays signed in and says so")
check(Account.everywhereAnswer(status: 200, data: nil) == .signOutHere && Account.everywhereAnswer(status: 401, data: nil) == .signOutHere, "everywhere: 200 or 401 signs out here (the page's rule)")
check(Account.everywhereAnswer(status: 503, data: json(#"{"error":"try again shortly"}"#)) == .stay("Try again shortly."), "everywhere: a refusal keeps the sign-in and gives the reason")
check(Account.everywhereAnswer(status: nil, data: nil) == .stay(Account.reach), "everywhere: no answer")
check(Account.errorWords(json(#"{"error":"already said."}"#)) == "Already said.", "a message with its own full stop gets no second one")

section("the plan line (slice B2): the page's #plan-line test, and nothing that sells")
let A = Account.planActive
check(A == "Kosmos+ \u{00B7} Active", "the page's words: Kosmos+ · Active")
check(Account.planLine(json(#"{"kosmos_plus":true}"#)) == A, "kosmos_plus true, no standing: shown")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":"good"}"#)) == A, "standing good: shown")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":null}"#)) == A, "standing null is falsy: shown")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":""}"#)) == A, "standing empty is falsy: shown")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":false}"#)) == A, "standing false is falsy: shown")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":0}"#)) == A, "standing 0 is falsy: shown")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":"past_due"}"#)) == nil, "standing past_due: hidden")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":"suspended"}"#)) == nil, "standing suspended: hidden")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":1}"#)) == nil, "standing 1 is truthy and not good: hidden")
check(Account.planLine(json(#"{"kosmos_plus":false}"#)) == nil, "kosmos_plus false: hidden")
check(Account.planLine(json(#"{"kosmos_plus":1}"#)) == nil, "kosmos_plus 1 is not === true: hidden")
check(Account.planLine(json(#"{"kosmos_plus":"true"}"#)) == nil, "kosmos_plus \"true\" is not === true: hidden")
check(Account.planLine(json(#"{"email":"a@example.com"}"#)) == nil, "no kosmos_plus (a sign-in answer): hidden")
check(Account.planLine(json("not json")) == nil && Account.planLine(nil) == nil, "unreadable or no answer: hidden")
check(Account.planLine(json(#"[true]"#)) == nil, "not an object: hidden")
section("the standing note (review 1): the server's sentence, as the page's #standing-note shows it")
typealias N = Account.StandingNote
check(Account.standingNote(json(#"{"kosmos_plus":false,"standing":"lapsed","standing_note":"The subscription on this account has lapsed."}"#)) == N(words: "The subscription on this account has lapsed.", calm: false), "a lapsed account: the server's words, as an error")
check(Account.standingNote(json(#"{"standing_note":"This account does not have a Kosmos+ subscription yet.","standing_note_calm":true}"#)) == N(words: "This account does not have a Kosmos+ subscription yet.", calm: true), "never paid, no computer: calm")
check(Account.standingNote(json(#"{"standing_note":"x","standing_note_calm":false}"#))?.calm == false, "calm false: an error")
check(Account.standingNote(json(#"{"standing_note":"x","standing_note_calm":"yes"}"#))?.calm == true && Account.standingNote(json(#"{"standing_note":"x","standing_note_calm":""}"#))?.calm == false, "calm as the page's !!: a non-empty string is calm, an empty one is not")
check(Account.standingNote(json(#"{"standing_note":""}"#)) == nil, "an empty sentence is falsy: nothing")
check(Account.standingNote(json(#"{"standing_note":null}"#)) == nil && Account.standingNote(json(#"{"kosmos_plus":true}"#)) == nil, "null or absent: nothing")
check(Account.standingNote(json(#"{"standing_note":5}"#)) == nil, "not a string: nothing")
check(Account.standingNote(nil) == nil && Account.standingNote(json("no")) == nil, "no answer or unreadable: nothing")
check(Account.planLine(json(#"{"kosmos_plus":true,"standing":"good"}"#)) != nil && Account.standingNote(json(#"{"kosmos_plus":true,"standing":"good"}"#)) == nil, "a good plan: the line and no note")
check(Account.isObject(json(#"{"kosmos_plus":true}"#)) && !Account.isObject(json("<html>")) && !Account.isObject(json("[1]")) && !Account.isObject(nil), "isObject: only a JSON object is an account answer")
check(Account.planSpoken == "Kosmos+, Active", "VoiceOver: the plan line as words")
section("one /me answer (review 3): replace, clear, or keep what is shown")
let good = json(#"{"kosmos_plus":true,"standing":"good"}"#)
check(Account.planAnswer(status: 200, data: good) == .show(line: A, note: nil, name: .none, email: nil), "200 with the account: the line")
check(Account.planAnswer(status: 200, data: json(#"{"kosmos_plus":false,"standing_note":"Lapsed."}"#)) == .show(line: nil, note: N(words: "Lapsed.", calm: false), name: .none, email: nil), "200, not good: no line, the note")
check(Account.planAnswer(status: 200, data: json("<html>captive</html>")) == .keep, "200 that is not JSON: keep")
check(Account.planAnswer(status: 200, data: nil) == .keep, "200 with no body: keep")
check(Account.planAnswer(status: 201, data: good) == .show(line: A, note: nil, name: .none, email: nil) && Account.planAnswer(status: 299, data: good) == .show(line: A, note: nil, name: .none, email: nil), "any 2xx with the account: the line")
check(Account.planAnswer(status: 304, data: good) == .keep && Account.planAnswer(status: 300, data: good) == .keep, "3xx: keep")
check(Account.planAnswer(status: 401, data: nil) == .clear, "401: clear")
check(Account.planAnswer(status: 403, data: good) == .keep, "403: keep")
check(Account.planAnswer(status: 429, data: nil) == .keep, "429: keep")
check(Account.planAnswer(status: 503, data: json("<html>maintenance</html>")) == .keep, "503 maintenance page: keep")
check(Account.planAnswer(status: nil, data: nil) == .keep, "no answer: keep")
let me = Account.meRequest(coordinator: coordinator, session: "tok")
check(me.url?.absoluteString == "https://login.kosmosplus.com/v1/account/me", "me: the account route")
check(me.httpMethod == "GET" && me.httpBody == nil, "me: a GET with no body")
check(me.value(forHTTPHeaderField: "Authorization") == "Bearer tok", "me: the session as the bearer")
check(me.timeoutInterval == 15, "me: gives up after 15 s, as the account's other asks")
check(!me.httpShouldHandleCookies && me.cachePolicy == .reloadIgnoringLocalCacheData, "me: no cookies, no cache")

section("who is signed in (slice B3): the page's #signed-in-as")
check(Account.signedInAs(json(#"{"email":"ada@example.com"}"#)) == "ada@example.com", "the account's email")
check(Account.signedInAs(json(#"{"email":""}"#)) == nil && Account.signedInAs(json(#"{"email":5}"#)) == nil && Account.signedInAs(nil) == nil, "empty, not a string, or no answer: nothing")
check(Account.planAnswer(status: 200, data: json(#"{"email":"ada@example.com","kosmos_plus":true}"#)) == .show(line: A, note: nil, name: .none, email: "ada@example.com"), "the /me answer carries it")

section("no computer yet (slice B3 review 2): the page's words")
check(Account.noComputerHead == "No computer is connected yet.", "the page's heading")
check(Account.noComputerHow == "On the computer you want to reach, open Kosmos, go to Settings, then Kosmos+, and sign in with this email. If Kosmos isn't on it yet, install it there first.", "the page's steps")
check(!Account.noComputerHow.contains("http"), "no link")

section("the Kosmos+ address (slice B3): the page's #addr-line and #name-offer")
check(Account.nameState(json(#"{"addresses":[],"device_status":"allowed","account_address":"ada.kosmosplus.com","has_name":true}"#)) == .address("ada.kosmosplus.com"), "no computer, an own address: says it")
check(Account.nameState(json(#"{"addresses":["ada.kosmosplus.com"],"account_address":"ada.kosmosplus.com","has_name":true}"#)) == .none, "with a computer: the page does not say the address")
check(Account.nameState(json(#"{"addresses":[],"device_status":"denied","account_address":"ada.kosmosplus.com","has_name":false}"#)) == .none, "a refused device: neither")
check(Account.nameState(json(#"{"addresses":[],"has_name":false}"#)) == .offer, "no name, no computer: offered one")
check(Account.nameState(json(#"{"addresses":["x.kosmosplus.com"],"has_name":false}"#)) == .offer, "no name with an address listed: offered (the page's rule)")
check(Account.nameState(json(#"{"addresses":[],"has_name":false,"account_address":"ada.kosmosplus.com"}"#)) == .address("ada.kosmosplus.com"), "an own address wins over the offer")
check(Account.nameState(json(#"{"addresses":[],"has_name":0}"#)) == .none, "has_name 0 is not === false")
check(Account.nameState(json(#"{"addresses":[]}"#)) == .none, "an older server sends no has_name: no offer")
check(Account.nameState(json(#"{"addresses":[],"has_name":true,"account_address":""}"#)) == .none, "an empty address is no address")
check(Account.nameState(json(#"{"has_name":false}"#)) == .offer && Account.nameState(json(#"{"account_address":"a.kosmosplus.com"}"#)) == .address("a.kosmosplus.com"), "no addresses field reads as none")
check(Account.nameState(json("<html>")) == .none && Account.nameState(nil) == .none, "unreadable: neither")
check(Account.planAnswer(status: 200, data: json(#"{"addresses":[],"has_name":false}"#)) == .show(line: nil, note: nil, name: .offer, email: nil), "the /me answer carries the name state")

section("nameClean and nameValid: the page's, step for step")
check(Account.nameClean("Ada Lovelace") == "ada-lovelace", "lowercase, a space to a hyphen")
check(Account.nameClean("ada__ __love") == "ada-love", "a run of spaces and underscores is one hyphen")
check(Account.nameClean("a_é_b") == "a-b", "a dropped letter does not leave a doubled hyphen")
check(Account.nameClean("--ada") == "ada" && Account.nameClean(" ada") == "ada", "no leading hyphen")
check(Account.nameClean("ada-") == "ada-", "a trailing hyphen stays while typing")
check(Account.nameClean("Ada.Love!@#7") == "adalove7", "nothing but letters, digits and hyphens")
check(Account.nameClean(String(repeating: "a", count: 40)).count == 32, "at most 32")
check(Account.nameClean("") == "", "empty stays empty")
check(Account.nameClean("ada\u{200B}love") == "adalove", "U+200B is not JavaScript's \\s: dropped, as on the page")
check(Account.nameClean("ada\u{FEFF}love") == "ada-love" && Account.nameClean("ada\u{3000}love") == "ada-love" && Account.nameClean("ada\u{00A0}love") == "ada-love", "U+FEFF, U+3000 and U+00A0 are: a hyphen, as on the page")
check(Account.nameClean("ada\u{0085}love") == "adalove", "U+0085 is not JavaScript's \\s: dropped")
check(Account.nameValid("ada") && Account.nameValid("a-1") && Account.nameValid(String(repeating: "a", count: 32)), "valid: 3 to 32, alnum at each end")
check(!Account.nameValid("ab") && !Account.nameValid(String(repeating: "a", count: 33)), "too short or too long")
check(!Account.nameValid("ada-") && !Account.nameValid("-ada") && !Account.nameValid("ad_a") && !Account.nameValid("Ada"), "a hyphen at an end, an underscore or a capital: not valid")
check(Account.nameEcho("") == "yourname.kosmosplus.com" && Account.nameEcho("ada") == "ada.kosmosplus.com", "the preview, as #name-echo")

section("nameSuggest: eight from the alphabet without look-alikes")
struct Fixed: RandomNumberGenerator { var n: UInt64 = 0; mutating func next() -> UInt64 { n &+= 0x9E3779B97F4A7C15; return n } }
var g = Fixed()
let sug = Account.nameSuggest(using: &g)
check(sug.count == 8 && sug.allSatisfy { Account.nameAlphabet.contains($0) }, "eight characters, all from the alphabet")
check(!Account.nameAlphabet.contains("0") && !Account.nameAlphabet.contains("o") && !Account.nameAlphabet.contains("1") && !Account.nameAlphabet.contains("l") && !Account.nameAlphabet.contains("i"), "no 0 o 1 l i")
check(Account.nameAlphabet.count == 31, "the page's 31 characters")
check(Account.nameValid(Account.nameSuggest()), "a suggestion is a valid name")

section("saving the name")
let nr = Account.nameRequest(coordinator: coordinator, session: "tok", name: "ada")
check(nr.url?.absoluteString == "https://login.kosmosplus.com/v1/account/name" && nr.httpMethod == "POST", "a POST to the name route")
check(nr.value(forHTTPHeaderField: "Authorization") == "Bearer tok", "the session as the bearer")
check((try? JSONSerialization.jsonObject(with: nr.httpBody ?? Data())) as? [String: String] == ["name": "ada"], "the body is the name alone")
check(Account.nameAnswer(status: 200, data: json(#"{"name":"ada","address":"ada.kosmosplus.com"}"#)) == .saved(address: "ada.kosmosplus.com"), "saved: the address from Kosmos+")
check(Account.nameAnswer(status: 200, data: json(#"{"name":"ada"}"#)) == .refused("That name is not available."), "a 200 with no address is not saved")
check(Account.nameAnswer(status: 409, data: json(#"{"error":"that name is taken"}"#)) == .refused("That name is taken."), "taken: Kosmos+'s sentence")
check(Account.nameAnswer(status: 400, data: nil) == .refused("That name is not available."), "a refusal without words: the page's")
check(Account.nameAnswer(status: 402, data: json(#"{"error":"This computer needs an address you have bought. Otherwise buy one at https://login.kosmosplus.com/buy, then sign in again.","code":"address_not_bought"}"#)) == .refused(Account.nameNotHere), "address_not_bought: never the buy sentence (kosmos#718)")
check(Account.nameAnswer(status: 409, data: json(#"{"error":"buy one","code":"address_not_bought"}"#)) == .refused(Account.nameNotHere), "the code alone is enough")
check(Account.nameAnswer(status: 402, data: nil) == .refused(Account.nameNotHere), "a 402 alone is enough")
check(Account.nameAnswer(status: nil, data: nil) == .refused("Kosmos could not be reached just now."), "no answer: the page's words")
check(Account.nameAnswer(status: 503, data: json("<html>maintenance</html>")) == .refused(Account.nameUnreachable) && Account.nameAnswer(status: 500, data: json(#"{"error":"boom"}"#)) == .refused(Account.nameUnreachable), "a 5xx is unreachable, not a judgement on the name")
check(!Account.nameNotHere.lowercased().contains("buy") && !Account.nameNotHere.contains("iPhone") && !Account.nameNotHere.contains("http"), "the 402's own words point nowhere")

print("")
print(failed == 0 ? "VERDICT: PASS \(passed)/\(passed + failed)" : "VERDICT: FAIL \(failed) of \(passed + failed)")
exit(failed == 0 ? 0 : 1)
